// One-time script: sets a representative photo for every item, grouped by
// category, sourced from Wikimedia Commons (properly licensed, not scraped
// from an image search -- see credits below). Run this ONCE, not from a
// button in the app, since it's a bulk data-seeding operation, not a
// feature -- see README.md if you want to re-run it or add more categories
// later.
//
// HOW TO RUN:
//   1. Open admin.html in your browser and sign in as an Admin.
//   2. Open the browser DevTools console (F12, or Ctrl+Shift+J / Cmd+Opt+J).
//   3. Paste this entire file's contents into the console and press Enter.
//   4. Watch the console for progress -- it uploads 14 photos (one per
//      category) to the item-photos bucket, then updates every SKU in each
//      category to point at its category's photo. Takes a few seconds.
//
// This OVERWRITES any photo already set on an item (matches what you asked
// for -- "add to all items"). Uploads use upsert, so running this again
// later just replaces the same 14 files rather than piling up duplicates.
//
// Requires the updated schema.sql (item-photos bucket, skus.image_path) to
// already be applied -- run that first if you haven't.

const CATEGORY_PHOTOS = {"Cement": {"dataUrl": "data:image/jpeg;base64,", "credit": "Volkan Yalcin, CC BY-SA 3.0, via Wikimedia Commons", "sourceFile": "Cement_bags.jpg", "bytes": 39336}, "Steel": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Concrete_rebar_0030.jpg", "bytes": 31906}, "Aggregate": {"dataUrl": "data:image/jpeg;base64,", "credit": "James St. John, CC BY 2.0, via Wikimedia Commons", "sourceFile": "Crushed_limestone_gravel_piles_(Maxville_Limestone,_Mississippian;_quarry_near_East_Fultonham,_Muskingum_County,_Ohio,_USA)_12_(30106034027).jpg", "bytes": 58160}, "Pipe & Fittings": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "PVC_Pipe.jpg", "bytes": 14431}, "Hardware": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Bolt_nut.jpg", "bytes": 10172}, "Electrical": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Power_cables.jpg", "bytes": 19732}, "Sanitary Ware": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Bathroom_sink.jpg", "bytes": 18446}, "Paint": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Spray_Paint_Can.png", "bytes": 16425}, "Lumber": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Wood_planks.jpg", "bytes": 27254}, "Cleaning Supplies": {"dataUrl": "data:image/jpeg;base64,", "credit": "CC BY-SA 3.0, via Wikimedia Commons", "sourceFile": "Spray_bottle.jpg", "bytes": 8441}, "Flooring": {"dataUrl": "data:image/jpeg;base64,", "credit": "CC BY-SA 4.0, via Wikimedia Commons", "sourceFile": "Vinyl_flooring,_tiles.jpg", "bytes": 13445}, "Ceiling": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Suspended-ceiling-0a.jpg", "bytes": 25095}, "Furniture": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Desk_chair.jpg", "bytes": 20696}, "Curtains & Blinds": {"dataUrl": "data:image/jpeg;base64,", "credit": "via Wikimedia Commons", "sourceFile": "Window_blinds.jpg", "bytes": 26140}}
;

async function importCategoryPhotos() {
  const entries = Object.entries(CATEGORY_PHOTOS);
  console.log(`Importing ${entries.length} category photos...`);
  let totalUpdated = 0;

  for (const [category, { dataUrl, credit, sourceFile }] of entries) {
    try {
      const res = await fetch(dataUrl);
      const blob = await res.blob();
      const slug = category.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
      const path = `category/${slug}.jpg`;

      const { error: uploadErr } = await supabaseClient.storage
        .from('item-photos')
        .upload(path, blob, { contentType: 'image/jpeg', upsert: true });
      if (uploadErr) throw uploadErr;

      const { data: updated, error: updateErr } = await supabaseClient
        .from('skus')
        .update({ image_path: path })
        .eq('category', category)
        .select('id');
      if (updateErr) throw updateErr;

      totalUpdated += updated?.length || 0;
      console.log(`OK  ${category.padEnd(20)} -> ${path}  (${updated?.length || 0} items)  [${credit}, ${sourceFile}]`);
    } catch (err) {
      console.error(`FAILED  ${category}:`, err.message || err);
    }
  }

  console.log(`Done. ${totalUpdated} items updated across ${entries.length} categories.`);
  console.log('Reload Manage Items / Stock to see the photos.');
}

importCategoryPhotos();
